using System;
using System.IO;
using System.Drawing;
using WoWProbe;
class FishingClientTests
{
    static int passed,failed;
    static void Check(bool yes){if(!yes)throw new Exception("Unexpected fishing client behavior");}
    static void Reject(Action action){try{action();}catch(FormatException){return;}throw new Exception("Invalid input accepted");}
    static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static FishingClientSettings Settings(){var s=new FishingClientSettings{Fishing=FishingFixtures.Plan(),UseAudio=false};s.VisualRegion=new FishingRegion{X=.3,Y=.3,Width=.1,Height=.1};s.Points.Add(new FishingPoint{X=.1,Y=.1});s.Points.Add(new FishingPoint{X=.2,Y=.1});s.Points.Add(new FishingPoint{X=.2,Y=.2});return s;}
    static QuickScreenText L(string s,int x=10){return new QuickScreenText{Text=s,X=x,Y=10,Width=100,Height=20};}
    static void Sum(byte[] b){int a=0,c=0;for(int i=0;i<126;i++){a=(a+b[i])%255;c=(c+a)%255;}b[126]=(byte)a;b[127]=(byte)c;}
    static int Main()
    {
        Test("all active cast stages block auxiliary actions including held keys",()=>{foreach(var phase in new[]{"WaitBite","ReelDelay","WaitLoot","Vendor","Stopped"})Check(!FishingCycleBoundary.IsIdle(phase,false));foreach(var phase in new[]{"Ready","PreCast","RecastDelay","RestoreFacing"}){Check(FishingCycleBoundary.IsIdle(phase,false));Check(!FishingCycleBoundary.IsIdle(phase,true));}Check(FishingCycleBoundary.IsIdle(null,false));});
        Test("new profile defaults stay ten minutes with independently optional social features",()=>{var s=new FishingClientSettings();Check(s.StayMinutes==10&&s.RandomSpots&&!s.ChatAtLap&&!s.WhisperReply&&!s.TimedSessions);});
        Test("profile roundtrip preserves points ranges and visual area",()=>{var s=Settings();s.TimedSessions=true;s.WhisperReply=true;s.CastDelay=new FishingRange(.34,.87);string path=Path.GetTempFileName();try{s.Save(path);var copy=FishingClientSettings.Load(path);copy.Validate(true);Check(copy.Points.Count==3&&copy.CastDelay.Min==.34&&copy.WhisperReply&&copy.VisualRegion.Width==.1);copy.Points[0].X=.9;Check(s.Points[0].X==.1);}finally{File.Delete(path);}});
        Test("invalid ranges null ranges and missing visual selection are rejected",()=>{var s=Settings();s.ReelDelay.Max=1.1;Reject(()=>s.Validate(true));s.ReelDelay=new FishingRange(.8,.1);Reject(()=>s.Validate(true));s.ReelDelay=null;Reject(()=>s.Validate(false));s=Settings();s.VisualRegion=new FishingRegion();Reject(()=>s.Validate(true));});
        Test("startup joins a shoreline edge and uses the shared vertex",()=>{var s=Settings();var picker=new FishingSpotPicker(s,n=>n/2);var target=picker.Next();var r=picker.Travel(new FarmObservation{X=.2,Y=.17},target,-1);Check(r.Points.Count==4);Check(r.Points[1].X==.2&&r.Points[1].Y==.2);Check(r.Points[2].X==.1&&r.Points[2].Y==.1);Check(r.Points[3].X==target.X);});
        Test("adjacent segment change passes the shared vertex rather than crossing water",()=>{var s=Settings();var picker=new FishingSpotPicker(s,n=>n/2);var a=picker.Next();var b=picker.Next();var r=picker.Travel(new FarmObservation{X=a.X,Y=a.Y},b,0);Check(r.Points.Count==3&&r.Points[1].X==.2&&r.Points[1].Y==.1);});
        Test("unrelated OK buttons and incomplete login pages are not login evidence",()=>{Check(!FishingLoginScreen.Login(new[]{L("登录")}));Check(!FishingLoginScreen.Disconnected(new[]{L("确定")}));Check(FishingLoginScreen.Login(new[]{L("Account"),L("Password"),L("Log In")}));Check(FishingLoginScreen.Disconnected(new[]{L("您已断开连接"),L("确定")}));Check(FishingLoginScreen.Find(new[]{L("确定"),L("确定",100)},"确定")==null);Check(!FishingLoginScreen.Same(L("确定"),L("确定",90)));});
        Test("actual Lua WF1 packet decodes with sender and active reply target",()=>{var b=File.ReadAllBytes("test-output/lua-fishing-packet.bin");var s=FishingSocialObservation.Decode(b,b[4]+256*b[5]);Check(s.Known&&s.WhisperCount==2&&s.SenderHash!=0&&s.Whisper&&s.ReplyTargetHash==s.SenderHash&&s.BagsKnown&&s.BagsOpen);Reject(()=>FishingSocialObservation.Decode(b,(b[4]+256*b[5]+1)%65536));b[50]=1;Reject(()=>FishingSocialObservation.Decode(b,b[4]+256*b[5]));Sum(b);Reject(()=>FishingSocialObservation.Decode(b,b[4]+256*b[5]));});
        Test("one thousand short unique phrases load and consecutive draws differ",()=>{var p=new FishingPhrases("assets/fishing/chat-phrases.txt",n=>0);var a=p.Next();Check(a.Length>0&&p.Next()!=a);});
        Test("recording keeps moving samples and accepts a stationary finish after UI delay",()=>{long now=0;var plan=FishingFixtures.Plan();var f=FishingFixtures.Observation(plan).Game.Farm;var recorder=new FishingRouteRecorder(plan.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;recorder.Observe(f,false);now=5000;recorder.Observe(f,true);Check(recorder.Finish().Count==2);});
        Test("recording rejects teleport while preserving recorded points",()=>{long now=0;var plan=FishingFixtures.Plan();var f=FishingFixtures.Observation(plan).Game.Farm;var recorder=new FishingRouteRecorder(plan.Calibration,f,()=>now);now=100;f.X+=.2;bool rejected=false;try{recorder.Observe(f,true);}catch(InvalidOperationException){rejected=true;}Check(rejected&&recorder.Count==1);});
        Test("short read interruptions recover moving samples instead of permanently latching after three seconds",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=3400;f.Sequence++;f.X+=.003;Check(r.Observe(f,false));now=12500;f.Sequence++;f.X+=.004;Check(r.Observe(f,false));now=13000;f.Sequence++;f.X+=.001;Check(r.Observe(f,true)&&r.Finish().Count==4);});
        Test("a long stationary handoff finishes without rejecting the existing route",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);now=120000;f.Sequence++;r.Observe(f,true);Check(r.Finish().Count==2);});
        Test("endpoint read failure ends into a recoverable draft without fabricating coordinates",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);string path=Path.GetTempFileName();try{var result=FishingRecordingFinalizer.Finish(r,()=>{throw new InvalidOperationException("missing grid");},path);Check(!result.Complete&&result.Points.Count==2&&result.Message.Contains("missing grid"));var saved=FishingRecordingDraft.Load(path);Check(saved.Points.Count==2&&saved.LastX==f.X);}finally{File.Delete(path);}});
        Test("genuinely missing long section saves draft and reports exact recovery coordinates",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);double last=f.X;now=30000;f.Sequence++;f.X+=.01;string path=Path.GetTempFileName();try{var result=FishingRecordingFinalizer.Finish(r,()=>f,path);var saved=FishingRecordingDraft.Load(path);Check(!result.Complete&&saved.LastX==last&&saved.Points.Count==2&&result.Message.Contains(r.Location));}finally{File.Delete(path);}});
        Test("draft resumes at saved endpoint and can finish after recording more points",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);var saved=r.Draft();var resumed=FishingRouteRecorder.Resume(saved,f,()=>now);now=1000;f.Sequence++;f.Y+=.001;resumed.Observe(f,true);Check(resumed.Finish().Count==3&&saved.Points.Count==2);bool blocked=false;f.X+=.1;try{FishingRouteRecorder.Resume(saved,f);}catch(InvalidOperationException){blocked=true;}Check(blocked);});
        Test("cross-map endpoint is saved only as incomplete draft",()=>{long now=0;var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);f.MapId++;string path=Path.GetTempFileName();try{var result=FishingRecordingFinalizer.Finish(r,()=>f,path);Check(!result.Complete&&FishingRecordingDraft.Load(path).Map.MapId==p.Calibration.MapId);}finally{File.Delete(path);}});
        Test("valid finish creates an independent service route with the exact observed endpoint",()=>{long now=0;var p=FishingFixtures.Plan();p.Calibration.Confirmed=true;var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);now=500;f.Sequence++;f.X+=.001;r.Observe(f,false);now=700;f.Sequence++;f.X+=.000001;string path=Path.GetTempFileName();try{var done=FishingRecordingFinalizer.Finish(r,()=>f,path);var original=new QuickRoutePlan();var service=FishingRecordingFinalizer.Service(original,p.Calibration,done.Points,f,"商人",true);service.Validate(true);Check(done.Complete&&service.Vendor.X==f.X&&service.Repair.X==f.X&&original.Vendor.Points.Count==0);}finally{File.Delete(path);}});
        Test("one-point finish persists a draft instead of trapping the finish operation",()=>{var p=FishingFixtures.Plan();var f=FishingFixtures.Observation(p).Game.Farm;var r=new FishingRouteRecorder(p.Calibration,f,()=>0);string path=Path.GetTempFileName();try{var result=FishingRecordingFinalizer.Finish(r,()=>f,path);Check(!result.Complete&&FishingRecordingDraft.Load(path).Points.Count==1);}finally{File.Delete(path);}});
        Test("water selection accepts either drag direction and survives settings roundtrip",()=>{var a=FishingRegion.FromSelection(new Point(100,60),new Point(300,180),new Size(1000,600));var b=FishingRegion.FromSelection(new Point(300,180),new Point(100,60),new Size(1000,600));Check(a.Valid&&a.X==b.X&&a.Y==b.Y&&a.Width==.2&&a.Height==.2);var s=Settings();s.VisualRegion=a;string path=Path.GetTempFileName();try{s.Save(path);var loaded=FishingClientSettings.Load(path);Check(loaded.VisualRegion.Valid&&loaded.VisualRegion.X==.1);}finally{File.Delete(path);}});
        Test("a picture without a drag and a tiny click do not count as a saved water selection",()=>{Check(!new FishingRegion().Valid);Check(!FishingRegion.FromSelection(new Point(100,100),new Point(100,100),new Size(1000,600)).Valid);Check(!FishingRegion.FromSelection(new Point(100,100),new Point(102,102),new Size(1000,600)).Valid);});
        Test("water selection clips out-of-window drags and editing clones preserves original on cancel",()=>{var original=FishingRegion.FromSelection(new Point(-20,-30),new Point(1200,800),new Size(1000,600));Check(original.Valid&&original.Width==1&&original.Height==1);var copy=original.Clone();copy.Width=.2;Check(original.Width==1);Check(!FishingRegion.FromSelection(new Point(1,1),new Point(2,2),new Size(0,0)).Valid);});
        Test("manual route recording tolerates movement faster than automatic navigation calibration",()=>{long now=0;var p=FishingFixtures.Plan();p.Calibration.AxisScale=1.5;p.Calibration.ForwardUnitsPerSecond=.008;var f=FishingFixtures.Observation(p).Game.Farm;f.X=.48910;f.Y=.12564;var r=new FishingRouteRecorder(p.Calibration,f,()=>now);foreach(var xy in new[]{new[]{.49788,.12154},new[]{.50446,.11844},new[]{.51109,.11533},new[]{.51767,.11223},new[]{.52385,.10945},new[]{.52902,.11478},new[]{.53018,.12413},new[]{.53070,.13265}}){now+=400;f.Sequence++;f.X=xy[0];f.Y=xy[1];Check(r.Observe(f,false));}Check(r.Finish().Count==9);});
        Test("disabled random fishing chooses the nearest saved point instead of forcing point A",()=>{var s=Settings();s.RandomSpots=false;var picker=new FishingSpotPicker(s);var chosen=picker.Start(new FarmObservation{X=.201,Y=.201});Check(picker.Segment==2&&chosen.X==s.Points[2].X&&chosen.Y==s.Points[2].Y&&picker.CompletedLaps==0);});
        Test("fast movement converges at the saved point then restores facing and reaches cast",()=>{
            foreach(double actualSpeed in new[]{.032,.064}){
                var s=Settings();s.RandomSpots=false;s.Fishing.Calibration.Confirmed=true;s.Fishing.Calibration.FacingSign=-1;s.Fishing.Calibration.ForwardUnitsPerSecond=.008;s.Fishing.Calibration.TurnRadiansPerSecond=5.85;s.Points[0].Facing=2.88;
                var from=new FarmObservation{X=.095,Y=.112};var picker=new FishingSpotPicker(s);var point=picker.Start(from);var route=picker.Travel(from,point,-1);var nav=new Navigator(route,s.Fishing.Calibration,false,false,1,NavigationPurpose.VendorReturn);
                var cal=s.Fishing.Calibration;var sample=new NavigationSample{Fresh=true,KnownCore=true,MapId=cal.MapId,MapMode=cal.MapMode,Zone=cal.Zone,X=from.X,Y=from.Y};long time=0;bool arrived=false;
                for(int i=0;i<400;i++){sample.Sequence++;var n=nav.Step(sample,time);if(n.Action==NavigationAction.Completed){arrived=true;break;}Check(n.Action!=NavigationAction.Stop);
                    var target=route.Points[n.TargetIndex];double compass=NavigationMath.Normalize(cal.FacingSign*sample.Facing+cal.FacingOffset);
                    if(n.Action==NavigationAction.Forward){n.HoldMilliseconds=FishingTravelPolicy.ForwardHold(NavigationMath.Distance(target.X-sample.X,target.Y-sample.Y,cal.AxisScale),target.Tolerance,.008);double distance=actualSpeed*n.HoldMilliseconds/1000;sample.X+=Math.Sin(compass)*distance/cal.AxisScale;sample.Y-=Math.Cos(compass)*distance;}
                    else if(n.Action==NavigationAction.TurnLeft||n.Action==NavigationAction.TurnRight){double bearing=Math.Atan2((target.X-sample.X)*cal.AxisScale,-(target.Y-sample.Y));n.HoldMilliseconds=FishingTravelPolicy.FacingHold(NavigationMath.Normalize(bearing-compass),5.85);compass+=(n.Action==NavigationAction.TurnRight?1:-1)*6.28*n.HoldMilliseconds/1000;sample.Facing=NavigationMath.PositiveAngle(cal.FacingSign*(compass-cal.FacingOffset));}
                    time+=n.HoldMilliseconds+100;
                }
                if(!arrived)throw new Exception("Did not converge: "+sample.X+","+sample.Y+" "+nav.LastReason);var plan=s.At(point);plan.Settings.CastDelayMinMs=plan.Settings.CastDelayMaxMs=0;var engine=new FishingEngine(plan);var o=FishingFixtures.Observation(plan);o.Game.Farm.X=sample.X;o.Game.Farm.Y=sample.Y;o.Game.Farm.Facing=sample.Facing;bool cast=false;
                for(int i=0;i<100;i++){long now=time+i*200;FishingFixtures.Frame(o,now);var cmd=engine.Step(o,now);if(cmd.Action==FishingAction.Stop)throw new Exception(cmd.Reason);if(cmd.Purpose==FishingPurpose.Cast){cast=true;break;}if(cmd.Purpose==FishingPurpose.RestoreFacing){double direction=cmd.Key==plan.Movement.TurnRight?-1:1;o.Game.Farm.Facing=NavigationMath.PositiveAngle(o.Game.Farm.Facing+direction*6.28*cmd.HoldMilliseconds/1000);}}
                Check(cast&&engine.Casts==1);
            }
        });
        Test("focus recovery waits for stable foreground released modifiers and closed chat",()=>{
            var gate=new FishingFocusRecovery();gate.Suspend();Check(!gate.ResumeReady(1000,false,true,true));Check(!gate.ResumeReady(2000,true,false,true));Check(!gate.ResumeReady(3000,true,true,false));
            Check(!gate.ResumeReady(4000,true,true,true));Check(!gate.ResumeReady(4499,true,true,true));Check(gate.ResumeReady(4500,true,true,true)&&!gate.Waiting);
        });
        Test("another focus interruption resets the resume countdown",()=>{
            var gate=new FishingFocusRecovery();gate.Suspend();Check(!gate.ResumeReady(0,true,true,true));Check(!gate.ResumeReady(400,false,true,true));Check(!gate.ResumeReady(500,true,true,true));Check(!gate.ResumeReady(999,true,true,true));Check(gate.ResumeReady(1000,true,true,true));
        });
        Test("only explicit focus and modifier interruptions may recover automatically",()=>{
            foreach(var reason in new[]{"Target window lost foreground.","Target window lost foreground during CLI operation.","Target window lost foreground during CLI checks.","A user-held modifier stopped fishing.","等待用户松开修饰键。"})Check(FishingFocusRecovery.Transient(reason));
            foreach(var reason in new[]{"Emergency stop.","用户停止钓鱼。","Fishing key release failed.","Fishing input destination or emergency state changed.","CLI observations are unavailable, unknown or stale.","当前地图与保存钓点不同。"})Check(!FishingFocusRecovery.Transient(reason));
        });
        Test("bag and periodic key features do not require WF1 social feedback",()=>{
            var s=Settings();s.PeekBags=s.TimedKeyEnabled=true;s.Validate(true);Check(!s.RequiresSocialFeedback());s.ChatAtLap=true;Check(s.RequiresSocialFeedback());s.ChatAtLap=false;s.WhisperReply=true;Check(s.RequiresSocialFeedback());
        });
        Test("timed key settings survive save import and cloning with legacy defaults",()=>{
            var s=Settings();Check(!s.TimedKeyEnabled&&s.TimedKey==8&&s.KeyMinutes.Min==10&&s.KeyMinutes.Max==15);s.TimedKeyEnabled=true;s.TimedKey=0;s.KeyMinutes=new FishingRange(11,14);string path=Path.GetTempFileName();
            try{s.Save(path);var loaded=FishingClientSettings.Load(path);Check(loaded.TimedKeyEnabled&&loaded.TimedKey==0&&loaded.KeyMinutes.Min==11&&loaded.KeyMinutes.Max==14);var copy=loaded.Clone();copy.KeyMinutes.Min=12;Check(loaded.KeyMinutes.Min==11);
                var json=File.ReadAllText(path);json=System.Text.RegularExpressions.Regex.Replace(json,",?\"TimedKeyEnabled\":true","");json=System.Text.RegularExpressions.Regex.Replace(json,",?\"TimedKey\":0","");json=System.Text.RegularExpressions.Regex.Replace(json,",?\"KeyMinutes\":\\{[^}]*\\}","");File.WriteAllText(path,json);var legacy=FishingClientSettings.Load(path);Check(!legacy.TimedKeyEnabled&&legacy.TimedKey==8&&legacy.KeyMinutes.Min==10);
            }finally{File.Delete(path);}
        });
        Test("invalid timed key or interval cannot be started",()=>{
            var s=Settings();s.TimedKey=12;Reject(()=>s.Validate(true));s=Settings();s.KeyMinutes=new FishingRange(15,10);Reject(()=>s.Validate(true));s=Settings();s.KeyMinutes=null;Reject(()=>s.Validate(false));
        });
        Test("each random segment faces its saved interpolated water direction before casting",()=>{
            foreach(double sign in new[]{-1.0,1.0}){var s=Settings();s.Fishing.Calibration.FacingSign=sign;s.Points[0].Facing=6.22;s.Points[1].Facing=.08;s.Points[2].Facing=.4;var picker=new FishingSpotPicker(s,n=>n/2);
                for(int segment=0;segment<3;segment++){var target=picker.Next();var f=new FarmObservation{Facing=NavigationMath.PositiveAngle(target.Facing+2.8),X=target.X,Y=target.Y};bool done=false;
                    for(int i=0;i<70;i++){var c=FishingArrivalFacing.Next(f,target,s.Fishing.Calibration,s.Fishing.Movement);if(c.Action==FishingAction.None){done=true;break;}Check(c.Key==s.Fishing.Movement.TurnRight||c.Key==s.Fishing.Movement.TurnLeft);f.Facing=NavigationMath.PositiveAngle(f.Facing+sign*(c.Key==s.Fishing.Movement.TurnRight?1:-1)*6.28*c.HoldMilliseconds/1000.0);}
                    Check(done&&Math.Abs(NavigationMath.Normalize(target.Facing-f.Facing))<=.10&&f.X==target.X&&f.Y==target.Y);
                    var plan=s.At(target);plan.Settings.CastDelayMinMs=plan.Settings.CastDelayMaxMs=0;var o=FishingFixtures.Observation(plan);o.Game.Farm.Facing=f.Facing;Check(new FishingEngine(plan).Step(o,0).Purpose==FishingPurpose.Cast);
                }
            }
        });
        Test("matched real packet merge preserves WP1 loot state through WO4 application and cloning",()=>{
            var combat=CombatPacket.Decode(File.ReadAllBytes("test-output/lua-operations-combat.bin"));var ops=OperationsPacket.Decode(File.ReadAllBytes("test-output/lua-operations-packet.bin"));
            for(int state=0;state<3;state++){var core=File.ReadAllBytes("test-output/lua-operations-core.bin");core[125]=(byte)((core[125]&~64)|(state==0?0:64));core[6]=(byte)((core[6]&~64)|(state==2?64:0));Sum(core);
                var merged=OperationObservation.FromPackets(ProbePacket.Decode(core),combat,ops,true);Check(merged.Fresh&&merged.LootWindowKnown==(state!=0)&&merged.LootWindowOpen==(state==2));ops.ApplyTo(merged);var copy=merged.Clone();Check(copy.LootWindowKnown==(state!=0)&&copy.LootWindowOpen==(state==2));
            }
        });
        Test("decoded closed loot state permits empty reel recast without inventing a catch",()=>{
            var core=File.ReadAllBytes("test-output/lua-operations-core.bin");core[125]|=64;core[6]=(byte)(core[6]&~64);Sum(core);var merged=OperationObservation.FromPackets(ProbePacket.Decode(core),CombatPacket.Decode(File.ReadAllBytes("test-output/lua-operations-combat.bin")),OperationsPacket.Decode(File.ReadAllBytes("test-output/lua-operations-packet.bin")),true);
            var p=FishingFixtures.Plan();var o=FishingFixtures.Observation(p);o.Game.LootWindowKnown=merged.LootWindowKnown;o.Game.LootWindowOpen=merged.LootWindowOpen;var e=new FishingEngine(p);e.Step(o,0);
            FishingFixtures.Frame(o,1000);o.Game.Farm.Channeling=true;o.LastBiteAtMs=1000;o.BiteConfidence=.95;e.Step(o,1000);FishingFixtures.Frame(o,1200);o.Game.Farm.Channeling=false;e.Step(o,1200);FishingFixtures.Frame(o,1700);e.Step(o,1700);FishingFixtures.Frame(o,1800);Check(e.Step(o,1800).Purpose==FishingPurpose.Cast&&e.Casts==2&&e.ConfirmedCatches==0);
        });
        Test("legacy single stay duration imports as equal bounds and new ranges and retry settings roundtrip",()=>{
            var s=Settings();s.StayMinutes=12.5;Check(s.StayInterval().Min==12.5&&s.StayInterval().Max==12.5&&!s.AutoRetry&&s.RetrySeconds==30);s.StayRange=new FishingRange(10,15);s.AutoRetry=true;s.RetrySeconds=47;string path=Path.GetTempFileName();
            try{s.Save(path);var loaded=FishingClientSettings.Load(path);Check(loaded.StayInterval().Min==10&&loaded.StayInterval().Max==15&&loaded.AutoRetry&&loaded.RetrySeconds==47);var copy=loaded.Clone();copy.StayRange.Min=11;Check(loaded.StayRange.Min==10);}finally{File.Delete(path);}
        });
        Test("invalid stay bounds or restart delay cannot start",()=>{var s=Settings();s.StayRange=new FishingRange(15,10);Reject(()=>s.Validate(false));s=Settings();s.RetrySeconds=0;Reject(()=>s.Validate(false));s.RetrySeconds=3601;Reject(()=>s.Validate(false));});
        Console.WriteLine("Fishing client: "+passed+" passed, "+failed+" failed. Pure/synthetic checks; no game input.");return failed==0?0:1;
    }
